// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import { AlertDialog } from "@/registry/erbium/ui/alert-dialog";

import type { Meta, StoryObj } from "@storybook/react";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import {\n  AlertDialog,\n  AlertDialogTrigger,\n  AlertDialogContent,\n  AlertDialogHeader,\n  AlertDialogTitle,\n  AlertDialogDescription,\n  AlertDialogFooter,\n  AlertDialogAction,\n  AlertDialogCancel,\n} from \"@/registry/erbium/ui/alert-dialog\";\nimport { Button } from \"@/registry/erbium/ui/button\";\n\nconst Example = (args: { size: \"default\" | \"sm\"; defaultOpen: boolean }) => (\n  <AlertDialog key={String(args.defaultOpen)} defaultOpen={args.defaultOpen}>\n    <AlertDialogTrigger render={<Button variant=\"outline\">Open alert dialog</Button>} />\n    <AlertDialogContent size={args.size}>\n      <AlertDialogHeader>\n        <AlertDialogTitle>Confirm action</AlertDialogTitle>\n        <AlertDialogDescription>This action needs confirmation.</AlertDialogDescription>\n      </AlertDialogHeader>\n      <AlertDialogFooter>\n        <AlertDialogCancel>Cancel</AlertDialogCancel>\n        <AlertDialogAction>Continue</AlertDialogAction>\n      </AlertDialogFooter>\n    </AlertDialogContent>\n  </AlertDialog>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/alert-dialog-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import BasicExample from "./variants/basic";

const BasicSource = "import { AlertDialogBasic } from \"../examples/upstream/alert-dialog-basic\";\n\nconst Example = () => <AlertDialogBasic />;\n\nexport default Example;\n";

import SmallExample from "./variants/small";

const SmallSource = "import { AlertDialogSmall } from \"../examples/upstream/alert-dialog-small\";\n\nconst Example = () => <AlertDialogSmall />;\n\nexport default Example;\n";

import MediaExample from "./variants/media";

const MediaSource = "import { AlertDialogWithMedia } from \"../examples/upstream/alert-dialog-media\";\n\nconst Example = () => <AlertDialogWithMedia />;\n\nexport default Example;\n";

import SmallMediaExample from "./variants/small-media";

const SmallMediaSource = "import { AlertDialogSmallWithMedia } from \"../examples/upstream/alert-dialog-small-media\";\n\nconst Example = () => <AlertDialogSmallWithMedia />;\n\nexport default Example;\n";

import ErrorVariantExample from "./variants/error-variant";

const ErrorVariantSource = "import { AlertDialogError } from \"../examples/upstream/alert-dialog-error\";\n\nconst Example = () => <AlertDialogError />;\n\nexport default Example;\n";

const meta = {
  title: "UI/Alert Dialog",
  component: AlertDialog,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "A modal dialog that interrupts the user with important content and expects a response.\n\n**Import:** `@/registry/erbium/ui/alert-dialog`\n\n## Usage\n\n```tsx\nimport {\n  AlertDialog,\n  AlertDialogAction,\n  AlertDialogCancel,\n  AlertDialogContent,\n  AlertDialogDescription,\n  AlertDialogFooter,\n  AlertDialogHeader,\n  AlertDialogTitle,\n  AlertDialogTrigger,\n} from \"@/registry/erbium/ui/alert-dialog\"\nimport {{ Button }} from \"@/registry/erbium/ui/button\"\n```\n\n```tsx\n<AlertDialog>\n  <AlertDialogTrigger render={<Button variant=\"outline\" />}>Show Dialog</AlertDialogTrigger>\n  <AlertDialogContent>\n    <AlertDialogHeader>\n      <AlertDialogTitle>Are you absolutely sure?</AlertDialogTitle>\n      <AlertDialogDescription>\n        This action cannot be undone. This will permanently delete your account from our servers.\n      </AlertDialogDescription>\n    </AlertDialogHeader>\n    <AlertDialogFooter>\n      <AlertDialogCancel>Cancel</AlertDialogCancel>\n      <AlertDialogAction>Continue</AlertDialogAction>\n    </AlertDialogFooter>\n  </AlertDialogContent>\n</AlertDialog>\n```\n\n## Composition\n\nUse the following composition to build an `AlertDialog`:\n\n```text\nAlertDialog\n├── AlertDialogTrigger\n└── AlertDialogContent\n    ├── AlertDialogHeader\n    │   ├── AlertDialogMedia\n    │   ├── AlertDialogTitle\n    │   └── AlertDialogDescription\n    └── AlertDialogFooter\n        ├── AlertDialogCancel\n        └── AlertDialogAction\n```",
      },
    },
  },
} satisfies Meta<typeof AlertDialog>;

export default { ...meta,  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{ size: "default" | "sm"; defaultOpen: boolean }> = {
  args: { size: "default", defaultOpen: false },
  argTypes: {
    size: { control: "select", options: ["default", "sm"] },
    defaultOpen: { control: "boolean" },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Basic: Story = {
  parameters: {
    docs: {
      description: { story: "A basic alert dialog with a title, description, and cancel and continue buttons." },
      source: { code: BasicSource },
    },
  },
  render: BasicExample,
};

export const Small: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `size=\"sm\"` prop to make the alert dialog smaller." },
      source: { code: SmallSource },
    },
  },
  render: SmallExample,
};

export const Media: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `AlertDialogMedia` component to add a media element such as an icon or image to the alert dialog." },
      source: { code: MediaSource },
    },
  },
  render: MediaExample,
};

export const SmallMedia: Story = {
  name: "Small with Media",
  parameters: {
    docs: {
      description: { story: "Use the `size=\"sm\"` prop to make the alert dialog smaller and the `AlertDialogMedia` component to add a media element such as an icon or image to the alert dialog." },
      source: { code: SmallMediaSource },
    },
  },
  render: SmallMediaExample,
};

export const ErrorVariant: Story = {
  name: "Error",
  parameters: {
    docs: {
      description: { story: "Use the `AlertDialogAction` component to add a error action button to the alert dialog." },
      source: { code: ErrorVariantSource },
    },
  },
  render: ErrorVariantExample,
};

import { HugeiconsIcon } from "@hugeicons/react";
import Delete02Icon from "@hugeicons/core-free-icons/Delete02Icon";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/registry/erbium/ui/alert-dialog";
import { Button } from "@/registry/erbium/ui/button";

export function AlertDialogError() {
  return (
    <AlertDialog>
      <AlertDialogTrigger render={<Button variant="error">Delete Chat</Button>} />
      <AlertDialogContent size="sm">
        <AlertDialogHeader>
          <AlertDialogMedia className="bg-error/10 text-error dark:bg-error/20 dark:text-error">
            <HugeiconsIcon icon={Delete02Icon} />
          </AlertDialogMedia>
          <AlertDialogTitle>Delete chat?</AlertDialogTitle>
          <AlertDialogDescription>
            This will permanently delete this chat conversation. View <a href="#">Settings</a>{" "}
            delete any memories saved during this chat.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel variant="outline">Cancel</AlertDialogCancel>
          <AlertDialogAction variant="error">Delete</AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

import { AlertDialogBasic } from "../examples/upstream/alert-dialog-basic";

const Example = () => <AlertDialogBasic />;

export default Example;

import { AlertDialogError } from "../examples/upstream/alert-dialog-error";

const Example = () => <AlertDialogError />;

export default Example;

import { AlertDialogWithMedia } from "../examples/upstream/alert-dialog-media";

const Example = () => <AlertDialogWithMedia />;

export default Example;

import Demo from "../examples/alert-dialog-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;

import { AlertDialogSmallWithMedia } from "../examples/upstream/alert-dialog-small-media";

const Example = () => <AlertDialogSmallWithMedia />;

export default Example;

import { AlertDialogSmall } from "../examples/upstream/alert-dialog-small";

const Example = () => <AlertDialogSmall />;

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}
